import datetime
import time

class TimeUtils:

    DATE_FORMAT = "%Y-%m-%d"
    TIME_FORMAT = "%H:%M:%S"
    DATETIME_FORMAT = "%Y-%m-%d %H:%M:%S"
    SECONDS_PER_MINUTE = 60

    def __init__(self):
        self._datetime = datetime.datetime.now()

    @property
    def datetime(self):
        return self._datetime

    @datetime.setter
    def datetime(self, value):
        self._datetime = value

    def get_current_time(self):
        return self._format_time(self._datetime, self.TIME_FORMAT)

    def get_current_date(self):
        return self._format_date(self._datetime, self.DATE_FORMAT)

    def add_seconds(self, seconds):
        new_datetime = self._datetime + datetime.timedelta(seconds=seconds)
        return self._format_time(new_datetime, self.TIME_FORMAT)

    def string_to_datetime(self, string):
        return datetime.datetime.strptime(string, self.DATETIME_FORMAT)

    def datetime_to_string(self, dt):
        return self._format_datetime(dt, self.DATETIME_FORMAT)

    def get_minutes(self, string_time1, string_time2):
        time1 = self.string_to_datetime(string_time1)
        time2 = self.string_to_datetime(string_time2)
        return self._calculate_minutes(time2, time1)

    def get_format_time(self, year, month, day, hour, minute, second):
        time_item = datetime.datetime(year, month, day, hour, minute, second)
        return self._format_datetime(time_item, self.DATETIME_FORMAT)

    def _format_time(self, dt, fmt):
        return dt.strftime(fmt)

    def _format_date(self, dt, fmt):
        return dt.strftime(fmt)

    def _format_datetime(self, dt, fmt):
        return dt.strftime(fmt)

    def _calculate_minutes(self, time2, time1):
        return round((time2 - time1).seconds / self.SECONDS_PER_MINUTE)
